    "id": "tts-voices-cached-empty",
    "severity": "blocking",
    "since": "2026-09-15",
    "failureMessage": "speechSynthesis.getVoices() answers with an empty list until the browser has finished loading voices, so a cache taken at module scope stays empty for the life of the page — every utterance then speaks in whatever voice the OS defaults to, with nothing thrown and nothing logged to say the preferred voice was never found",
    "scanFileClasses": ["javascriptFiles"],
    "excludeFileClasses": ["testFiles"],
    "excludeFiles": "/(^|\\/)(node_modules|dist|build|out|coverage|vendor|third_party)\\//",
    "scanIgnoringComments": true,
    "matchLines": [
      {
        "match": "/^(?:const|let|var)\\s+\\w+\\s*=\\s*(?:(?:window|globalThis|self)\\.)?speechSynthesis\\.getVoices\\s*\\(\\s*\\)/",
        "unlessFileMatches": "/voiceschanged/",
        "what": "caches getVoices() at module scope, which runs before the browser has any voices to give",
        "fix": "resolve the voice inside speak() and never keep an empty result — fall back to the default for that utterance and resolve again on the next one; a module-scope cache is only sound when a `voiceschanged` listener refreshes it"
      }
    ]
  }
]

